import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['DIR','DL','RSPP-A','RSPP-AGG']
EA(K,'S15','La gestione del cambiamento',[SC("La nuova macchina in arrivo","Tra due mesi arriva un centro di lavoro robotizzato che sostituirà due fresatrici. L’ufficio acquisti ha già firmato l’ordine.",[
 ("Quando va coinvolta la prevenzione?",[["Prima dell’installazione: valutazione preventiva con RSPP, medico competente e consultazione dell’RLS",True,"Corretto: i cambiamenti si valutano prima che producano effetti."],["Dopo il primo mese di produzione",False,"I rischi vanno valutati prima."],["Mai, la macchina è marcata CE",False,"La marcatura non sostituisce la valutazione dell’uso nel contesto."]]),
 ("Che cosa verifichi alla consegna?",[["Marcatura CE, dichiarazione di conformità, istruzioni in italiano e corretta installazione secondo le istruzioni",True,"Corretto."],["Solo il collaudo produttivo",False,"Non riguarda la sicurezza."],["La garanzia commerciale",False,"Non basta."]]),
 ("Che cosa aggiorni prima dell’avvio?",[["DVR, procedure, formazione e addestramento degli operatori, manutenzione programmata",True,"Corretto."],["Solo l’inventario dei cespiti",False,"Non basta."],["Nulla",False,"Il cambiamento modifica i rischi."]])],
 "Valutare prima, verificare alla consegna, aggiornare documenti e competenze prima dell’avvio: la gestione del cambiamento evita che i nuovi rischi arrivino senza difese.","Una nuova macchina sta per arrivare. Organizza la gestione del cambiamento.","Artt. 28, 29, 70 e 71 D.lgs. 81/2008 · UNI EN ISO 45001, punto 8.1.3")])
EA(K,'S16','La stima del rischio: R = P × D',[LB("Laboratorio · Stimare e ordinare i rischi","Stimi con la matrice 4 × 4 i rischi emersi nel sopralluogo di un magazzino.",[
  ["Rischio A","investimento di pedoni da carrelli in corsie senza separazione: eventi già accaduti nel settore, possibili lesioni gravi"],["Rischio B","tagli da taglierini durante l’apertura dei colli: frequenti, lesioni lievi"],["Rischio C","caduta di colli dall’ultimo livello della scaffalatura: improbabile, conseguenze gravissime"],["Rischio D","affaticamento visivo al terminale di accettazione: probabile, danno lieve"]],[
  ("Assegna probabilità e danno e calcola R per ogni rischio.",7,"A: P 3, D 3, R 9. B: P 4, D 1, R 4. C: P 1, D 4, R 4. D: P 3, D 1, R 3. I valori vanno motivati con dati, eventi e osservazioni.",["Ho assegnato P e D motivandoli","Ho calcolato R","Ho mantenuto coerenza nei criteri"],None,120),
  ("Stabilisci le priorità e spiega i limiti della matrice.",6,"Priorità al rischio A. B e C hanno lo stesso R ma natura diversa: C, con danno gravissimo, merita attenzione anche se improbabile. La matrice semplifica: non sostituisce il giudizio né le valutazioni specifiche con metodi normati.",["Ho dato priorità ad A","Ho distinto B e C","Ho indicato i limiti"]),
  ("Proponi una misura per A e C con responsabile e scadenza.",6,"A: separazione fisica di percorsi pedonali e corsie dei carrelli, segnaletica e velocità ridotta; responsabile il dirigente di magazzino; entro tre mesi. C: verifica della scaffalatura, reti o protezioni anticaduta e regole di carico; responsabile ufficio tecnico; entro un mese.",["Ho proposto misure tecniche","Ho indicato responsabili","Ho indicato scadenze"])],
 "Nel laboratorio stimi quattro rischi di un magazzino con la matrice probabilità per danno, stabilisci le priorità e proponi le misure, poi confronta ogni risposta con la soluzione di riferimento.","Art. 28 D.lgs. 81/2008")])
EA(K,'S17','Data certa, firme e aggiornamento del DVR',[SC("Il DVR del 2015","Durante un audit scopri che il DVR di uno stabilimento risale al 2015. Da allora sono state introdotte due linee produttive e si è verificato un infortunio grave.",[
 ("Il DVR andava rielaborato?",[["Sì: modifiche significative del processo e infortuni significativi obbligano alla rielaborazione",True,"Corretto: art. 29, comma 3."],["No, il DVR non scade",False,"Non scade, ma va rielaborato quando cambiano le condizioni."],["Solo ogni dieci anni",False,"Non esiste una scadenza fissa."]]),
 ("Entro quando dopo le modifiche?",[["Entro 30 giorni dalle rispettive causali",True,"Corretto."],["Entro un anno",False,"Il termine è più breve."],["Alla prossima ispezione",False,"Non è un criterio."]]),
 ("Come dimostri la data del nuovo documento?",[["Con data certa o con le firme di datore di lavoro, RSPP, RLS e medico competente",True,"Corretto."],["Con la data nel nome del file",False,"Non è data certa."],["Con una e-mail interna",False,"Non basta di per sé."]])],
 "Il DVR non scade ma si rielabora entro trenta giorni da modifiche significative o infortuni significativi, con data certa o firme congiunte.","Un DVR fermo da anni. Valuta e rimedia.","Artt. 28 e 29 D.lgs. 81/2008")])
EA(K,'S18','A(8), classi di esposizione e rischio di vasculopatia',[LB("Laboratorio · Calcolare A(8) per le vibrazioni mano-braccio","Calcoli l’esposizione giornaliera di un addetto alla sbavatura.",[
  ["Utensile 1","smerigliatrice angolare, ahv = 6 m/s², 1 ora al giorno"],["Utensile 2","levigatrice orbitale, ahv = 3 m/s², 2 ore al giorno"],["Riferimenti","valore di azione 2,5 m/s²; valore limite 5 m/s²"]],[
  ("Calcola A(8).",7,"A(8) = √[(6² × 1 + 3² × 2) / 8] = √[(36 + 18) / 8] = √6,75 ≈ 2,6 m/s².",["Ho applicato la formula","Ho ottenuto circa 2,6 m/s²"]),
  ("Confronta con i valori di riferimento e indica gli obblighi.",5,"2,6 m/s² supera il valore di azione di 2,5 e resta sotto il limite di 5: servono un programma di misure tecniche e organizzative per ridurre l’esposizione, informazione e formazione specifiche e sorveglianza sanitaria.",["Ho confrontato con azione e limite","Ho indicato programma di misure e sorveglianza"]),
  ("Quale intervento riduce di più l’esposizione e di quanto?",6,"La smerigliatrice pesa di più: con un modello a basse vibrazioni da 4 m/s² A(8) = √[(16 + 18) / 8] ≈ 2,1 m/s², sotto il valore di azione. In alternativa ridurre il suo tempo d’uso a mezz’ora: √[(18 + 18) / 8] ≈ 2,1 m/s².",["Ho individuato il contributo maggiore","Ho ricalcolato A(8)","Ho proposto alternative"])],
 "Nel laboratorio calcoli l’esposizione giornaliera a vibrazioni mano-braccio di un addetto alla sbavatura, la confronti con i valori di riferimento e valuti l’intervento più efficace, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 201-204 D.lgs. 81/2008 · UNI EN ISO 5349")])
EA(K,'S19','Il limite di peso raccomandato: i fattori della UNI ISO 11228-1',[LB("Laboratorio · Il limite di peso raccomandato","Valuti un’operazione di sollevamento in una linea di confezionamento.",[
  ["Lavoratore","uomo tra 18 e 45 anni: massa di riferimento 25 kg"],["Geometria","distanza orizzontale H = 40 cm; altezza iniziale V = 30 cm; dislocazione D = 70 cm; asimmetria A = 30°"],["Frequenza","1 sollevamento al minuto per meno di un’ora: FM = 0,94"],["Presa","buona: CM = 1"],["Peso sollevato","12 kg"]],[
  ("Calcola i fattori HM, VM, DM e AM.",7,"HM = 25/40 = 0,625. VM = 1 − 0,003 × |30 − 75| = 0,865. DM = 0,82 + 4,5/70 ≈ 0,884. AM = 1 − 0,0032 × 30 = 0,904.",["Ho calcolato HM","Ho calcolato VM e DM","Ho calcolato AM"]),
  ("Calcola il limite raccomandato e l’indice di sollevamento.",6,"RWL = 25 × 0,625 × 0,865 × 0,884 × 0,904 × 0,94 × 1 ≈ 10,2 kg. LI = 12 / 10,2 ≈ 1,18: oltre 1, il rischio è presente e servono interventi.",["Ho calcolato circa 10,2 kg","Ho calcolato LI circa 1,18","Ho interpretato l’indice"]),
  ("Quale intervento abbassa l’indice e di quanto?",5,"Il fattore peggiore è la distanza orizzontale: avvicinando il carico a 25 cm, HM = 1 e RWL ≈ 16,2 kg, LI ≈ 0,74. Alzare il piano di prelievo a 75 cm porta VM a 1. Si possono combinare gli interventi.",["Ho individuato il fattore peggiore","Ho ricalcolato RWL e LI","Ho proposto interventi combinabili"])],
 "Nel laboratorio applichi i fattori della norma per calcolare il limite di peso raccomandato e l’indice di sollevamento di un’operazione di confezionamento, poi individui l’intervento più efficace. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 11228-1 · Allegato XXXIII D.lgs. 81/2008")])
EA(K,'S20','Lo stress lavoro-correlato: il metodo INAIL',[SC("La valutazione preliminare","In un call center con 60 operatori gli eventi sentinella mostrano assenze per malattia in forte aumento, turnover del 25% e tre segnalazioni del medico competente.",[
 ("Come procedi?",[["Completi la valutazione preliminare per gruppi omogenei con eventi sentinella, contenuto e contesto del lavoro, sentendo i lavoratori o l’RLS",True,"Corretto: è il percorso del metodo INAIL."],["Distribuisci un questionario a caso",False,"Il percorso ha fasi definite."],["Concludi che il rischio è basso",False,"Gli indicatori dicono il contrario."]]),
 ("La valutazione preliminare indica un rischio. Che cosa fai?",[["Adotti misure correttive e, se non efficaci, passi alla valutazione approfondita con strumenti soggettivi",True,"Corretto."],["Archivi il risultato",False,"Servono azioni."],["Licenzi gli operatori assenti",False,"È ingiustificato."]]),
 ("Quali misure correttive sono tipiche?",[["Revisione dei carichi e delle pause, chiarezza dei ruoli, formazione dei capi, canali di ascolto",True,"Corretto."],["Aumentare i controlli sulle assenze",False,"Non agisce sulle cause."],["Premi solo ai più produttivi",False,"Può peggiorare il clima."]])],
 "Il metodo INAIL parte da indicatori oggettivi per gruppi omogenei; se emerge un rischio servono misure correttive e, se non bastano, la valutazione approfondita.","Un call center con segnali di disagio. Imposta la valutazione.","Art. 28 D.lgs. 81/2008 · metodologia INAIL")])
EA(K,'S21','Lavoratrici in gravidanza e madri: la valutazione specifica',[SC("La comunicazione della gravidanza","Un’operaia addetta al carico manuale di casse da 15 kg comunica di essere in gravidanza.",[
 ("Che cosa fai subito?",[["La sposti a mansioni compatibili, perché il sollevamento di pesi è un lavoro vietato in gravidanza",True,"Corretto: lo prevede il D.lgs. 151/2001."],["Aspetti il parere del medico di famiglia",False,"Il datore di lavoro deve agire subito."],["Le chiedi di sollevare carichi più leggeri",False,"Il divieto riguarda il trasporto e sollevamento di pesi."]]),
 ("Se non esistono mansioni compatibili?",[["Si informa l’Ispettorato territoriale del lavoro, che può disporre l’interdizione dal lavoro",True,"Corretto."],["La lavoratrice resta a casa senza retribuzione",False,"Non è previsto."],["Continua la stessa mansione",False,"È vietato."]]),
 ("Che cosa deve contenere il DVR?",[["La valutazione dei rischi per gestanti, puerpere e madri in allattamento e le misure, con informazione a tutte le lavoratrici",True,"Corretto: art. 11 del D.lgs. 151/2001."],["Nulla, finché nessuna è in gravidanza",False,"La valutazione va fatta prima."],["Solo un elenco di nomi",False,"Non è una valutazione."]])],
 "La tutela della maternità si prepara nel DVR e si attua subito alla comunicazione: spostamento a mansioni compatibili o, se impossibile, interdizione disposta dall’Ispettorato.","Una lavoratrice in gravidanza addetta al carico manuale. Decidi le misure.","D.lgs. 151/2001, artt. 7, 11 e 12")])
EA(K,'S22','Verificare l’efficacia della formazione: il modello a quattro livelli',[LB("Laboratorio · Misurare l’efficacia di un corso","Progetti la verifica di efficacia del corso per i carrellisti dopo due quasi incidenti in magazzino.",[
  ["Corso","4 ore di aggiornamento con prova pratica"],["Partecipanti","14 carrellisti"],["Problemi osservati","velocità eccessiva in curva, carichi non stabilizzati, mancato uso della cintura"]],[
  ("Definisci un indicatore per ciascuno dei quattro livelli.",7,"Reazione: questionario di gradimento e utilità. Apprendimento: test e prova pratica con lista di controllo. Comportamento: osservazioni sul campo dopo uno e tre mesi su velocità, carichi e cintura. Risultati: quasi incidenti e danni a merci e scaffalature nei sei mesi successivi.",["Ho definito i quattro livelli","Ho reso osservabili i comportamenti","Ho scelto risultati misurabili"]),
  ("Come organizzi le osservazioni di comportamento?",6,"Lista di controllo con pochi comportamenti chiave, osservatori formati, ad esempio preposti, osservazioni brevi e ripetute, restituzione immediata ai lavoratori, registrazione dei dati per confrontare prima e dopo.",["Ho previsto una lista di controllo","Ho previsto osservatori e restituzione","Ho previsto il confronto prima-dopo"]),
  ("Se dopo tre mesi i comportamenti non migliorano?",5,"Si analizzano le cause, che spesso sono organizzative: ritmi, layout, pressioni produttive. Si interviene su di esse e si ripete l’addestramento mirato; la formazione da sola non basta.",["Ho cercato cause organizzative","Ho previsto azioni sull’organizzazione","Ho previsto addestramento mirato"])],
 "Nel laboratorio progetti la verifica di efficacia di un corso per carrellisti. Definisci indicatori per i quattro livelli, organizza le osservazioni e decidi che cosa fare se i comportamenti non cambiano, poi confronta ogni risposta con la soluzione di riferimento.","Accordo Stato-Regioni 17 aprile 2025 · modello di Kirkpatrick")])
EA(K,'S23','La documentazione della formazione',[SC("Le prove della formazione","Durante un controllo l’ispettore chiede di vedere la formazione di cinque lavoratori scelti a caso. Per due ci sono solo fogli firma senza programma né verifica.",[
 ("Che cosa manca?",[["Progetto formativo, verifica di apprendimento e attestato, oltre al registro",True,"Corretto: la documentazione deve dimostrare contenuti, durata e apprendimento."],["Nulla, la firma basta",False,"Non dimostra i contenuti né l’apprendimento."],["Solo la fotografia dell’aula",False,"Non è una prova."]]),
 ("Come rimedi?",[["Ripeti o integri la formazione con documentazione completa e organizzi un archivio per lavoratore",True,"Corretto."],["Ricostruisci i documenti a posteriori",False,"Sarebbe una falsificazione."],["Dichiari che è stata fatta",False,"Non basta."]]),
 ("Dove confluiranno i dati della formazione?",[["Nel fascicolo elettronico del lavoratore",True,"Corretto: introdotto dal D.L. 159/2025."],["Solo nell’archivio cartaceo",False,"Il sistema evolve verso il fascicolo elettronico."],["Nel DVR",False,"Il DVR contiene il programma, non i singoli attestati."]])],
 "La formazione si dimostra con progetto, registro, verifica e attestato, conservati per lavoratore e destinati al fascicolo elettronico.","Un ispettore verifica la formazione. Valuta le evidenze.","Art. 37 D.lgs. 81/2008 · Accordo 17 aprile 2025 · D.L. 159/2025")])
EA(K,'S24','Formare lavoratori stranieri',[SC("La squadra multilingue","In una cooperativa di logistica 12 nuovi addetti parlano cinque lingue diverse e capiscono poco l’italiano.",[
 ("Che cosa fai prima della formazione?",[["Verifichi la comprensione della lingua veicolare",True,"Corretto: art. 37, comma 13."],["Inizi subito in italiano",False,"La comprensione va verificata."],["Consegni il materiale tradotto con un traduttore automatico",False,"Va verificata la comprensione effettiva."]]),
 ("Come organizzi il corso?",[["Gruppi per lingua o mediatori culturali, linguaggio semplice, immagini e prove pratiche",True,"Corretto."],["Una lezione frontale lunga",False,"Poco efficace."],["Solo video in italiano",False,"Non garantisce la comprensione."]]),
 ("Come verifichi l’apprendimento?",[["Con prove pratiche e domande nella lingua compresa, documentando l’esito",True,"Corretto."],["Con un test scritto in italiano tecnico",False,"Misura la lingua, non la sicurezza."],["Non serve verificare",False,"La verifica è obbligatoria."]])],
 "Verifica della lingua, metodi comprensibili e verifiche adatte: la formazione è efficace solo se è compresa.","Lavoratori con lingue diverse da formare. Organizza il corso.","Art. 37, c. 13, D.lgs. 81/2008")])
EA(K,'S25','Consultazione e partecipazione: quando si consulta l’RLS',[CL("Consultazione obbligatoria?","Seleziona una decisione, poi se l’RLS va consultato.",["Consultazione obbligatoria","Non prevista come obbligo"],[
 ["Valutazione dei rischi e programma delle misure",0,"Art. 50, lett. b)."],["Designazione dell’RSPP e degli addetti alle emergenze",0,"Art. 50, lett. c)."],
 ["Organizzazione della formazione",0,"Art. 50, lett. d)."],["Scelta del fornitore di cancelleria",1,"Non riguarda la sicurezza."],
 ["Introduzione di una nuova tecnologia con effetti sulla sicurezza",0,"Rientra nella valutazione dei rischi."],["Fissazione del listino prezzi",1,"Non è una materia di consultazione."]],
 "Sei decisioni aziendali. Individua quelle per cui la consultazione dell’RLS è obbligatoria.","Art. 50 D.lgs. 81/2008")])
EA(K,'S26','La leadership visibile: i sopralluoghi della direzione',[LB("Laboratorio · Il sopralluogo di sicurezza della direzione","Prepari il primo sopralluogo di sicurezza del direttore di stabilimento.",[
  ["Reparto","stampaggio, 30 addetti su due turni"],["Tempo disponibile","30 minuti al mese"],["Contesto","molti quasi incidenti con i carrelli; clima teso dopo un infortunio"]],[
  ("Prepara la scaletta del sopralluogo.",6,"Breve preparazione con dati del reparto; ingresso con i DPI richiesti; osservazione di due o tre attività critiche, come movimentazione con carrelli; conversazione con due o tre lavoratori; riconoscimento dei comportamenti corretti; annotazione di non più di tre azioni.",["Ho previsto osservazione e ascolto","Ho previsto il riconoscimento","Ho limitato le azioni"]),
  ("Scrivi tre domande da porre ai lavoratori.",5,"Che cosa ti preoccupa di più durante il turno? Che cosa renderebbe più sicuro il tuo lavoro? Se segnali un problema, che cosa succede dopo? Domande aperte, senza cercare colpevoli.",["Ho scritto domande aperte","Ho evitato domande accusatorie"]),
  ("Come dai seguito al sopralluogo?",6,"Azioni registrate con responsabile e scadenza, comunicazione dell’esito al reparto, verifica al sopralluogo successivo, indicatori come numero di sopralluoghi e percentuale di azioni chiuse nei tempi.",["Ho previsto azioni tracciate","Ho previsto la restituzione al reparto","Ho previsto indicatori"])],
 "Nel laboratorio prepari il primo sopralluogo di sicurezza di un direttore di stabilimento: scaletta, domande ai lavoratori e seguito, poi confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 45001, punto 5.1")])
EA(K,'S27','Gli accomodamenti ragionevoli',[SC("La postazione per il lavoratore con disabilità","Un impiegato amministrativo, a seguito di un incidente, utilizza la sedia a ruote e deve rientrare al lavoro.",[
 ("Che cosa deve fare il datore di lavoro?",[["Adottare accomodamenti ragionevoli: accessibilità, postazione adattata, organizzazione del lavoro",True,"Corretto: è un obbligo per tutti i datori di lavoro."],["Assegnarlo a casa senza mansioni",False,"Sarebbe discriminatorio."],["Nulla se non lo chiede per iscritto",False,"L’obbligo esiste in ogni caso."]]),
 ("Quali aspetti di sicurezza aggiorni?",[["Piano di emergenza ed evacuazione con assistenza dedicata e vie di esodo accessibili",True,"Corretto: l’evacuazione deve essere possibile per tutti."],["Solo il badge",False,"Non basta."],["Nessuno",False,"La valutazione va aggiornata."]]),
 ("Quando l’accomodamento non è dovuto?",[["Quando comporta un onere sproporzionato, da valutare e motivare",True,"Corretto."],["Quando costa più di 100 €",False,"Non c’è una soglia fissa."],["Mai",False,"Il limite dell’onere sproporzionato esiste."]])],
 "Accomodamenti ragionevoli, piano di emergenza inclusivo e valutazione motivata dell’onere: così il rientro al lavoro avviene in sicurezza.","Un lavoratore in sedia a ruote rientra al lavoro. Organizza il rientro.","D.lgs. 216/2003, art. 3, c. 3-bis · D.M. 2 settembre 2021")])
